CREATE TABLE public.community_authority_guides (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), topic_ar text NOT NULL CHECK(length(trim(topic_ar)) BETWEEN 1 AND 300), topic_en text NOT NULL CHECK(length(trim(topic_en)) BETWEEN 1 AND 300), institution_type text NOT NULL CHECK(institution_type IN ('professional_syndicate','labour_organisation','civil_society','foundation','endowment','club','community_programme','general')), competent_body_name_ar text, competent_body_name_en text, summary_ar text, summary_en text, official_url text, source_name text, source_name_ar text, source_url text, verified_on date, languages text CHECK(languages IN ('ar','en','ar,en')), sort_order integer DEFAULT 0, review_status text NOT NULL DEFAULT 'needs_check' CHECK(review_status IN ('needs_check','editorial_reviewed','verified')), is_active boolean NOT NULL DEFAULT false, internal_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.community_authority_guides TO service_role;
REVOKE ALL ON public.community_authority_guides FROM anon,authenticated;
GRANT SELECT(id,slug,topic_ar,topic_en,institution_type,competent_body_name_ar,competent_body_name_en,summary_ar,summary_en,official_url,source_name,source_name_ar,source_url,verified_on,languages,sort_order,review_status,is_active,created_at,updated_at) ON public.community_authority_guides TO anon,authenticated;
GRANT INSERT,UPDATE,DELETE ON public.community_authority_guides TO authenticated;
ALTER TABLE public.community_authority_guides ENABLE ROW LEVEL SECURITY;
CREATE POLICY community_authority_guides_public ON public.community_authority_guides FOR SELECT TO anon,authenticated USING(is_active AND review_status IN ('editorial_reviewed','verified'));
CREATE POLICY community_authority_guides_admin ON public.community_authority_guides FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_community_authority_guide() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF NEW.verified_on > CURRENT_DATE THEN RAISE EXCEPTION 'Verification date cannot be in the future'; END IF;
 IF NEW.source_url IS NOT NULL AND (length(NEW.source_url)>2048 OR NEW.source_url !~ '^https?://' OR NEW.source_url ~* '\.pdf([?#]|$)') THEN RAISE EXCEPTION 'Source must be an HTTP website, not a PDF'; END IF;
 IF NEW.official_url IS NOT NULL AND (length(NEW.official_url)>2048 OR NEW.official_url !~ '^https://' OR NEW.official_url ~* '\.pdf([?#]|$)') THEN RAISE EXCEPTION 'Official URL must be HTTPS and not a PDF'; END IF;
 IF NEW.is_active AND (nullif(trim(NEW.source_url),'') IS NULL OR NEW.verified_on IS NULL OR NEW.review_status NOT IN ('editorial_reviewed','verified') OR coalesce(NEW.official_url,'') !~ '^https://') THEN RAISE EXCEPTION 'Activation requires source URL, verification date, reviewed status and HTTPS official URL'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER community_authority_guides_validate BEFORE INSERT OR UPDATE ON public.community_authority_guides FOR EACH ROW EXECUTE FUNCTION public.validate_community_authority_guide();
CREATE TRIGGER community_authority_guides_touch BEFORE UPDATE ON public.community_authority_guides FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
REVOKE ALL ON FUNCTION public.validate_community_authority_guide() FROM PUBLIC;
CREATE TABLE public.community_partner_interest (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_name text NOT NULL CHECK(length(trim(organisation_name)) BETWEEN 1 AND 200), country text NOT NULL CHECK(length(trim(country)) BETWEEN 1 AND 100), organisation_type text NOT NULL CHECK(organisation_type IN ('professional syndicate','labour organisation','civil society organisation','foundation','endowment administrator','club or resort operator','public or government body','company or supplier','other')), interests text[] NOT NULL CHECK(cardinality(interests) BETWEEN 1 AND 8 AND interests <@ ARRAY['institution directory','service applications','memberships','booking','governance tools','asset and endowment management','partnerships','training and volunteering']::text[]), contact_name text NOT NULL CHECK(length(trim(contact_name)) BETWEEN 1 AND 100), contact_email text NOT NULL CHECK(length(contact_email)<=255 AND contact_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), message text NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 1000), consent_given boolean NOT NULL CHECK(consent_given=true), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_review','resolved','dismissed')), created_at timestamptz NOT NULL DEFAULT now(), internal_notes text);
GRANT ALL ON public.community_partner_interest TO service_role;
REVOKE ALL ON public.community_partner_interest FROM anon,authenticated;
ALTER TABLE public.community_partner_interest ENABLE ROW LEVEL SECURITY;
CREATE INDEX community_partner_interest_created_at_idx ON public.community_partner_interest(created_at);
CREATE FUNCTION public.community_partner_interest_rate_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('community_partner_interest_rate_limit'));
 IF (SELECT count(*) FROM public.community_partner_interest WHERE created_at > now()-interval '1 minute') >= 30 THEN RAISE EXCEPTION 'Too many inquiries, please try again shortly'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER community_partner_interest_rate_limit BEFORE INSERT ON public.community_partner_interest FOR EACH ROW EXECUTE FUNCTION public.community_partner_interest_rate_limit();
REVOKE ALL ON FUNCTION public.community_partner_interest_rate_limit() FROM PUBLIC;
COMMENT ON TABLE public.community_partner_interest IS 'Private institution expressions of interest; server-only validated insert, role-checked central administrator reads and status edits; no direct visitor access.';